#include <iostream>
#include <vector>

using namespace std;

long long power(long long base, long long exponent) {
    long long result = 1;
    for (long long i = 0; i < exponent; ++i) {
        result *= base;
    }
    return result;
}

int digitSum(long long value) {
    int sum = 0;
    while (value > 0) {
        sum += value % 10;
        value /= 10;
    }
    return sum;
}

int main() {
    long long a, b, c;
    cin >> a >> b >> c;

    vector<long long> answers;

    for (int sum = 1; sum <= 81; ++sum) {
        long long x = b * power(sum, a) + c;
        if (x > 0 && x < 1000000000LL && digitSum(x) == sum) {
            answers.push_back(x);
        }
    }

    cout << answers.size() << '\n';
    for (size_t i = 0; i < answers.size(); ++i) {
        if (i > 0) cout << ' ';
        cout << answers[i];
    }
    cout << '\n';

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

long long pot(int xx, int yy)
{
    long long aa = 1;
    for (int ii = 0; ii < yy; ii++)
        aa *= xx;
    return aa;
}

int sumter(long long sd)
{
    long long asd = sd, mu = 0;
    for (int i = 0; i < 9; i++) {
        mu += asd % 10;
        asd /= 10;
    }
    return static_cast<int>(asd + mu);
}

int main()
{
    vector<int> myv;
    long long a, b, c, suma, x;

    cin >> a >> b >> c;

    if (b == 0) {
        cout << 1 << '\n' << 1 << '\n';
        return 0;
    }

    for (int i = 1; i <= 81; i++) {
        x = b * pot(i, a) + c;
        if (x < 0 || x > 999999999)
            continue;

        suma = sumter(x);
        if (suma == i)
            myv.push_back(static_cast<int>(x));
    }

    cout << myv.size() << '\n';
    for (size_t i = 0; i < myv.size(); i++) {
        if (i > 0)
            cout << ' ';
        cout << myv[i];
    }
    cout << '\n';

    return 0;
}

